#nullable enable // autogenerated

using MVZ2.Vanilla.Level;
using MVZ2Logic.Modding;
using PVZEngine;
using PVZEngine.Callbacks;

namespace MVZ2.GameContent.GlobalCallbacks
{
    [ModGlobalCallbacks]
    public class WindStageGlobalCallbacks : VanillaGlobalCallbacks
    {
        public override void Apply(Mod mod)
        {
            mod.AddTrigger(LevelCallbacks.POST_LEVEL_UPDATE, PostUpdateCallback);
        }
        private void PostUpdateCallback(LevelCallbackParams param, CallbackResult result)
        {
            var level = param.level;
            var targetWindSpeed = level.GetTargetDecorativeWindSpeed();
            var currentWindSpeed = level.GetCurrentDecorativeWindSpeed();
            currentWindSpeed = Ticks.SmoothDamp(currentWindSpeed, targetWindSpeed, 0.2f);
            level.SetCurrentDecorativeWindSpeed(currentWindSpeed);
        }
    }
}
